describe('Username Availability Validation', () => {
    beforeEach(() => {
        cy.visit('/signup'); // Adjust the URL to your application's signup page
    });

    it('should indicate username is available when a unique username is entered', () => {
        cy.get('input[name="username"]').type('uniqueUsername123');
        cy.intercept('GET', '/api/username-check?username=uniqueUsername123', {
            statusCode: 200,
            body: { available: true }
        }).as('checkUsername');
        cy.get('input[name="username"]').blur();
        cy.wait('@checkUsername');
        cy.get('.username-availability').should('contain', 'Username is available');
    });

    it('should indicate username is taken when a duplicate username is entered', () => {
        cy.get('input[name="username"]').type('takenUsername456');
        cy.intercept('GET', '/api/username-check?username=takenUsername456', {
            statusCode: 200,
            body: { available: false }
        }).as('checkUsername');
        cy.get('input[name="username"]').blur();
        cy.wait('@checkUsername');
        cy.get('.username-availability').should('contain', 'Username is already taken');
    });
});
